#include "ksNativeGlobalJob.h"
#include <vector>
#include <tuple>
#include <iostream>
#include <stdexcept>
using Event=std::tuple<bool,unsigned,unsigned,uint64_t>;
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
struct IO{ks::NativeGlobalContext&context;std::vector<uint8_t>memory;std::vector<Event>events;uint64_t now=1000;unsigned wait=0,reads=0,previous=~0u;IO(ks::NativeGlobalContext&c):context(c),memory(1<<24){}
 unsigned memoryWriteClocks(unsigned at){return at<0x400000&&!(previous&1)&&at==(previous|1u)?0:3;}
 unsigned readGlobal8(unsigned a,unsigned at){auto value=memory[a];events.emplace_back(false,a,value,now+at);return value;}
 unsigned readGlobal16(unsigned a,unsigned at){auto high=readGlobal8(a,at);return(high<<8)|readGlobal8(a+1,at);}
 unsigned readGlobal32(unsigned a,unsigned at){return(readGlobal16(a,at-3)<<16)|readGlobal16(a+2,at);}
 void writeGlobal8(unsigned a,uint8_t value,unsigned at){memory[a]=value;events.emplace_back(true,a,value,now+at);previous=a;}
 void writeGlobal16(unsigned a,uint16_t value,unsigned at){writeGlobal8(a,uint8_t(value>>8),at);writeGlobal8(a+1,uint8_t(value),at);if(a==0x174a8)context.dsp.primary=value;else if(a==0x174aa)context.dsp.alternate=value;else if(a==0x159f2)context.dsp.cached=value;}
 unsigned readRoute(ks::DspRoutingTask::Read r,unsigned at){using R=ks::DspRoutingTask::Read;switch(r){case R::PrimaryOffset:return readGlobal16(0x174a8,at);case R::AlternateOffset:return readGlobal16(0x174aa,at);case R::CachedAddress:return readGlobal16(0x159f2,at);case R::VoiceA:return readGlobal8(0x17526,at);case R::VoiceB:return readGlobal8(0x174a7,at);case R::VoiceBase:return readGlobal8(0x167ba,at);}return 0;}
 void writeRoute(ks::DspRoutingTask::Write w,uint16_t value,unsigned at){writeGlobal16(w==ks::DspRoutingTask::Write::PrimaryOffset?0x174a8:w==ks::DspRoutingTask::Write::AlternateOffset?0x174aa:0x159f2,value,at);}
 unsigned readDsp(ks::NativeDspJob::Port port,unsigned off,unsigned at){unsigned value=off==4?(reads++<wait?0:7):0;events.emplace_back(false,(port==ks::NativeDspJob::Port::A?0x400000:0x600000)+off,value,now+at);return value;}
 void writeDsp(ks::NativeDspJob::Port port,unsigned off,uint8_t value,unsigned at){events.emplace_back(true,(port==ks::NativeDspJob::Port::A?0x400000:0x600000)+off,value,now+at);previous=~0u;}
 unsigned readFault(ks::DspFaultTask::Read r,unsigned at){return readGlobal8(r==ks::DspFaultTask::Read::Latch?0xffec22:0xffff62,at);}
 void writeFault(ks::DspFaultTask::Write w,uint8_t value,unsigned at){writeGlobal8(w==ks::DspFaultTask::Write::Latch?0xffec22:w==ks::DspFaultTask::Write::Data?0xffff61:0xffff62,value,at);}
};int main(){try{unsigned cases=0;for(unsigned part=0;part<4;++part)for(unsigned input=0;input<256;++input)for(unsigned timingMode:{0u,1u}){ks::NativeGlobalContext context;IO io(context);io.events.reserve(16);auto set16=[&](unsigned at,uint16_t value){io.memory[at]=uint8_t(value>>8);io.memory[at+1]=uint8_t(value);};auto set32=[&](unsigned at,uint32_t value){set16(at,uint16_t(value>>16));set16(at+2,uint16_t(value));};auto read16=[&](unsigned at){return(uint16_t(io.memory[at])<<8)|io.memory[at+1];};unsigned control=0x174ae +part*20;set32(control,0x30000);io.memory[0x17526]=uint8_t(part);io.memory[0x167ba]=uint8_t((part+1)&3);set16(0x1512e,uint16_t(1000+input));set16(0x15132,uint16_t(input*257));set16(0x159f2,0xffff);for(unsigned field=0;field<256;++field){io.memory[0x30000+field]=uint8_t(input+field*17);io.memory[0x168fc+field]=uint8_t(input+field*19);}for(unsigned field:{95u,103u,113u,119u})io.memory[0x30000+field]=uint8_t(timingMode?1+(input&31):0);io.memory[0x30000+217]=uint8_t(input%7);for(unsigned row=0;row<6;++row)for(unsigned i=0;i<10;++i)set16(0x15282+row*20+i*2,uint16_t(input*257+row*149+i*37));context.dsp.part=uint8_t(part);context.dsp.basePart=io.memory[0x167ba];ks::NativeGlobalJob job(context);unsigned count=0;while(!job.complete()){io.events.clear();auto cost=job.nextClocks(io);check(cost,"stalled native global task");check(!job.advanceBefore(cost-1,io).clocks&&io.events.empty(),"early native global data");auto progress=job.advanceBefore(cost,io);io.now+=progress.clocks;check(progress.completed==job.complete(),"escaped child completion");check(++count<20000,"global graph cycle");}check(context.control==part&&context.part==part&&context.patch==0x30000,"typed resource binding");for(unsigned i=0;i<8;++i)check(io.memory[control+9+i]==uint8_t(input+(179+i)*17),"live control mirror copy");check(io.memory[0x160d2+part*334+313]==uint8_t(input+209*17),"pedal destination");unsigned row=input%7;if(row>5)row=5;unsigned seed=uint16_t(input*257+row*149+37),factor=uint16_t(input*257+row*149+74),bias=uint16_t(input*257+row*149+111);for(unsigned i=0;i<6;++i){check(read16(0x1752e +i*2)==seed,"matrix generated recurrence");seed=uint16_t((uint32_t(uint16_t(seed<<1))*factor)>>16);seed=uint16_t(seed+bias);check(read16(0x1753a+i*2)==uint16_t(input*257+row*149+(4+i)*37),"matrix source tail");}check(read16(0x174a8)==0&&read16(0x174aa)==0,"live routing reset");check(context.dsp.port==(part?ks::NativeDspJob::Port::A:ks::NativeDspJob::Port::B),"final optional effect DSP selection");++cases;}std::cout<<"PASS: "<<cases<<" ROM-free complete global graphs: resource binding, mirrored controls/pedal, independently calculated matrix recurrence/tail, DSP port/reset, timing budget and typed child completion\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
